def router_proxy_limiter(router_id):
    with ROUTER_PROXY_LOCK:
        limiter = ROUTER_PROXY_LIMITERS.get(router_id)
        if limiter is None:
            limiter = threading.BoundedSemaphore(ROUTER_PROXY_LIMIT)
