# BEGIN EMBEDDED MOBILE API
HUB_MOBILE_API_SHA256 = '4a1577c18dc40917f09a14feb5d1d10edf5e7c5b966450d50bac2c7bc8d2a174'
HUB_MOBILE_API_BUNDLE = ''
# END EMBEDDED MOBILE API


def hub_update_write(path, data, mode=0o600):
    """One durable atomic replacement; never truncate a running Hub or its state."""
    path = Path(path)
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix='.' + path.name + '-', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(name, mode)
        os.replace(name, path)
    finally:
        Path(name).unlink(missing_ok=True)


class HubUpdateSourceUnsupported(ValueError):
    """A valid older source cannot preserve capabilities of the installed Hub."""


def hub_mobile_api_payload(source=None):
    """Use the exact helper shipped in the confirmed Hub, without another URL."""
    digest, bundle = HUB_MOBILE_API_SHA256, HUB_MOBILE_API_BUNDLE
    if source is not None:
        values = {}
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', SyntaxWarning)
            tree = ast.parse(source)
        for node in tree.body:
            if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                name = node.targets[0].id
                if name in {'HUB_MOBILE_API_SHA256', 'HUB_MOBILE_API_BUNDLE'}:
                    values[name] = ast.literal_eval(node.value)
        if not values:
            raise HubUpdateSourceUnsupported(
                'Сборка в источнике обновлений пока не поддерживает приложение Android. '
                'Установленная панель и приложение продолжают работать; эта сборка пропущена.')
        digest, bundle = values.get('HUB_MOBILE_API_SHA256'), values.get('HUB_MOBILE_API_BUNDLE')
    if (not isinstance(digest, str) or not re.fullmatch('[a-f0-9]{64}', digest)
            or not isinstance(bundle, str) or len(bundle) > 262144):
        raise ValueError('В обновлении нет проверяемого модуля мобильного API.')
    unpack = zlib.decompressobj()
    data = unpack.decompress(base64.b64decode(bundle, validate=True), 131073)
    if not unpack.eof or unpack.unused_data or not 1000 <= len(data) <= 131072:
        raise ValueError('Некорректный размер модуля мобильного API.')
    if hashlib.sha256(data).hexdigest() != digest:
        raise ValueError('Контрольная сумма модуля мобильного API не совпала.')
    compile(data, 'mobile_api.py', 'exec', dont_inherit=True)
    return data, digest


def hub_preserve_mobile_api(source):
    """Retain newer additive native endpoints when a valid Hub ships an older helper.

    The effective candidate is revalidated and hashed after this bounded merge;
    it is exactly the file the user confirms and the worker checks before writing.
    """
    remote, _ = hub_mobile_api_payload(source)
    local, _ = hub_mobile_api_payload()
    def revision(data):
        for node in ast.parse(data).body:
            if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name) and node.targets[0].id == 'MOBILE_API_REVISION':
                value = ast.literal_eval(node.value)
                return value if isinstance(value, int) else 0
        return 1
    if revision(remote) >= revision(local):
        return source
    tree = ast.parse(source)
    # Only Hub builds with the same native API dispatch and boot protocol qualify.
    functions = {node.name: node for node in tree.body if isinstance(node, (ast.FunctionDef, ast.ClassDef))}
    if 'hub_prepare_mobile_api' not in functions or 'run_hub_update_worker' not in functions:
        raise HubUpdateSourceUnsupported('Обновите Hub до сборки с поддержкой мобильного API.')
    handler = functions.get('Handler')
    dispatch = ast.get_source_segment(source.decode('utf-8'), handler) if handler else ''
    if not dispatch or 'mobile_api.dispatch_get' not in dispatch or 'mobile_api.dispatch_post' not in dispatch:
        raise HubUpdateSourceUnsupported('Сборка Hub не поддерживает мобильные маршруты.')
    lines = source.decode('utf-8').splitlines(keepends=True)
    replacements = {'HUB_MOBILE_API_SHA256': HUB_MOBILE_API_SHA256, 'HUB_MOBILE_API_BUNDLE': HUB_MOBILE_API_BUNDLE}
    for node in reversed(tree.body):
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name) and node.targets[0].id in replacements:
            name = node.targets[0].id
            lines[node.lineno-1:node.end_lineno] = [name + ' = ' + repr(replacements[name]) + '\n']
    merged_text = ''.join(lines)
    # Carry the preservation policy through the first update from an older
    # published updater, so a second update cannot silently remove endpoints.
    manager = functions.get('HubUpdateManager')
    checker = next((node for node in manager.body if isinstance(node, ast.FunctionDef) and node.name == '_check'), None) if manager else None
    checker_source = ast.get_source_segment(source.decode('utf-8'), checker) if checker else ''
    if 'hub_preserve_mobile_api(data)' not in checker_source:
        if 'hub_mobile_api_payload(data)' not in checker_source:
            raise HubUpdateSourceUnsupported('Не удалось проверить протокол обновления мобильного API.')
        current_text = Path(__file__).read_text(encoding='utf-8')
        current_node = next(node for node in ast.parse(current_text).body if isinstance(node, ast.FunctionDef) and node.name == 'hub_preserve_mobile_api')
        policy = ast.get_source_segment(current_text, current_node)
        if 'hub_preserve_mobile_api' not in functions:
            merged_text += '\n\n' + policy + '\n'
            # The module's __main__ entry runs before appended definitions.
            entry = re.search(r'(?m)^if __name__ == [\"\']__main__[\"\']:', merged_text)
            if entry:
                merged_text = merged_text[:entry.start()] + policy + '\n\n' + merged_text[entry.start():]
                merged_text = merged_text.rsplit('\n\n' + policy + '\n', 1)[0]
        merged_text = merged_text.replace(checker_source, checker_source.replace('hub_mobile_api_payload(data)', 'data = hub_preserve_mobile_api(data)'), 1)
    merged = merged_text.encode('utf-8')
    hub_update_validate(merged)
    hub_mobile_api_payload(merged)
    return merged


def hub_prepare_mobile_api(target=None):
    """Bridge updates from older workers that only replace the main Hub file."""
    global mobile_api
    data, digest = hub_mobile_api_payload()
    path = Path(target or APP_DIR / 'mobile_api.py')
    try:
        if not path.exists() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            hub_update_write(path, data, 0o644)
    except OSError as exc:
        # The embedded, validated module can serve requests even on a read-only
        # installation. Desktop startup must not depend on writing a helper.
        print('Не удалось сохранить mobile_api.py; используется встроенный модуль: ' + str(exc), file=sys.stderr)
    module = type(sys)('mobile_api')
    module.__file__ = str(path)
    exec(compile(data, str(path), 'exec', dont_inherit=True), module.__dict__)
    sys.modules['mobile_api'] = module
    mobile_api = module
    return digest


def hub_log_maintenance_payload(source=None):
    """The confirmed Hub includes its exact maintenance script: no second URL."""
    digest, bundle = HUB_LOG_MAINTENANCE_SHA256, HUB_LOG_MAINTENANCE_BUNDLE
    if source is not None:
        values = {}
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', SyntaxWarning)
            tree = ast.parse(source)
        for node in tree.body:
            if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                name = node.targets[0].id
                if name in {'HUB_LOG_MAINTENANCE_SHA256', 'HUB_LOG_MAINTENANCE_BUNDLE'}:
                    values[name] = ast.literal_eval(node.value)
        digest, bundle = values.get('HUB_LOG_MAINTENANCE_SHA256'), values.get('HUB_LOG_MAINTENANCE_BUNDLE')
    if not isinstance(digest, str) or not re.fullmatch('[a-f0-9]{64}', digest) or not isinstance(bundle, str):
        raise ValueError('В обновлении нет проверяемого скрипта обслуживания журналов.')
    unpack = zlib.decompressobj()
    data = unpack.decompress(base64.b64decode(bundle, validate=True), 131073)
    if not unpack.eof or unpack.unused_data or not 5000 <= len(data) <= 131072:
        raise ValueError('Некорректный размер скрипта обслуживания журналов.')
    if hashlib.sha256(data).hexdigest() != digest:
        raise ValueError('Контрольная сумма скрипта обслуживания журналов не совпала.')
    compile(data, 'log-maintenance.py', 'exec', dont_inherit=True)
    return data, digest


def hub_log_maintenance_directory(directory, job_id):
    if not re.fullmatch('[a-f0-9]{32}', str(job_id)):
        raise ValueError('Некорректный идентификатор обновления.')
    return Path(directory) / ('log-maintenance-' + job_id)


def hub_log_maintenance_receipt(directory, job_id):
    try:
        path = hub_log_maintenance_directory(directory, job_id) / 'receipt.json'
        with path.open('rb') as stream:
            data = json.loads(stream.read(8193))
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def hub_log_maintenance_command(args, deadline):
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise RuntimeError('Истекло время настройки обслуживания журналов.')
    result = subprocess.run(args, capture_output=True, text=True, errors='replace',
                            timeout=remaining, env={**os.environ, 'DEBIAN_FRONTEND': 'noninteractive'})
    if result.returncode:
        detail = ((result.stdout or '') + '\n' + (result.stderr or '')).strip()[-2000:]
        raise RuntimeError('Обслуживание журналов: rc=' + str(result.returncode) + '; ' + detail)
    return result


def hub_rollback_log_maintenance(directory, job_id):
    stage = hub_log_maintenance_directory(directory, job_id)
    if (stage / 'backup/manifest.json').is_file():
        hub_log_maintenance_command([sys.executable, str(stage / 'log-maintenance.py'), 'rollback',
                                     '--backup', str(stage / 'backup')], time.monotonic() + 45)


def hub_install_log_maintenance(directory, job_id, source=None, budget=120):
    data, digest = hub_log_maintenance_payload(source)
    stage = hub_log_maintenance_directory(directory, job_id)
    stage.mkdir(mode=0o700, parents=True, exist_ok=True)
    script, backup = stage / 'log-maintenance.py', stage / 'backup'
    receipt = {'job_id': job_id, 'sha256': digest, 'status': 'installing'}
    def save(status, error=''):
        receipt.update(status=status, error=error[:2000], updated_at=time.time())
        hub_update_write(stage / 'receipt.json', json.dumps(receipt, ensure_ascii=False).encode())
    hub_update_write(script, data, 0o700)
    save('installing')
    deadline = time.monotonic() + budget
    try:
        if not shutil.which('logrotate'):
            if not shutil.which('apt-get'):
                raise RuntimeError('Не найден logrotate и пакетный менеджер apt-get.')
            # Existing Ubuntu/Debian package indexes; never an unbounded apt update.
            hub_log_maintenance_command(['apt-get', '-o', 'DPkg::Lock::Timeout=5', 'install', '-y', 'logrotate'],
                                        min(deadline, time.monotonic() + 25))
        hub_log_maintenance_command([sys.executable, str(script), 'install', '--backup', str(backup)], deadline)
        hub_log_maintenance_command([sys.executable, str(script), 'run'], deadline)
        result = json.loads(HUB_LOG_MAINTENANCE_RESULT.read_text())
        if not result.get('ok') or result.get('day') != dt.date.today().isoformat():
            raise RuntimeError('Успешное обслуживание журналов за текущие сутки не подтверждено: ' + str(result.get('error', 'нет результата'))[:500])
        hub_log_maintenance_command(['systemctl', 'is-active', 'logrotate.timer'], deadline)
        hub_log_maintenance_command(['systemctl', 'is-enabled', 'logrotate.timer'], deadline)
        save('ready')
    except Exception as exc:
        reason = str(exc)
        try:
            hub_rollback_log_maintenance(directory, job_id)
        except Exception as rollback:
            reason += '; ошибка отката настроек журналов: ' + str(rollback)
        save('failed', reason)
        raise RuntimeError(reason) from exc
    return receipt


def hub_prune_log_maintenance_backups(directory, job_id):
    """Keep this update's snapshot and one prior snapshot, never router data."""
    current = hub_log_maintenance_directory(directory, job_id)
    old = sorted((p for p in Path(directory).iterdir() if p != current and not p.is_symlink()
                  and p.is_dir() and re.fullmatch('log-maintenance-[a-f0-9]{32}', p.name)),
                 key=lambda p: p.stat().st_mtime, reverse=True)
    for path in old[1:]:
        shutil.rmtree(path)


def run_hub_log_maintenance_worker(job_id, directory=None):
    directory = Path(directory or STATE_DIR / 'panel-update')
    job = hub_update_state(directory)
    if (job.get('id') != job_id or job.get('revision') != HUB_LOADED_REVISION
            or job.get('status') not in {'restarting', 'succeeded'}):
        raise RuntimeError('Задача установки обслуживания журналов устарела.')
    hub_install_log_maintenance(directory, job_id, budget=40)


def hub_run_log_maintenance_unit(directory, job_id, target):
    """PID 1 launches the worker outside Hub's restricted capability set.

    Keep the worker independent of Hub's service: an old updater can roll back
    the Hub while this unit safely finishes restoration of logging settings.
    Never chmod nginx logs or broaden the web service's capabilities.
    """
    hub_log_maintenance_directory(directory, job_id)  # Validate before naming a unit.
    result = subprocess.run([
        'systemd-run', '--quiet', '--wait', '--pipe', '--collect',
        '--unit=owrt-remote-log-maintenance-' + job_id,
        '--property=Type=exec', '--property=RuntimeMaxSec=100',
        '--setenv=OWRT_REMOTE_STATE_DIR=' + str(STATE_DIR),
        sys.executable, str(target), 'panel-log-maintenance-worker',
        '--job-id', job_id, '--directory', str(directory),
    ], capture_output=True, text=True, errors='replace', timeout=110)
    if result.returncode:
        detail = ((result.stdout or '') + '\n' + (result.stderr or '')).strip()[-2000:]
        raise RuntimeError('Задача обслуживания журналов: rc=' + str(result.returncode) + '; ' + detail)
    receipt = hub_log_maintenance_receipt(directory, job_id)
    if receipt.get('status') != 'ready' or receipt.get('sha256') != HUB_LOG_MAINTENANCE_SHA256:
        raise RuntimeError('Задача обслуживания журналов не подтвердила установку: ' + str(receipt.get('error', 'нет результата'))[:1000])


def hub_update_state(directory, value=None):
    path = Path(directory) / 'job.json'
    if value is not None:
        hub_update_write(path, json.dumps(value, ensure_ascii=False).encode('utf-8'))
        return value
    try:
        with path.open('rb') as stream:
            raw = stream.read(16385)
        data = json.loads(raw) if len(raw) <= 16384 else {}
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


@contextmanager
def hub_update_lock(directory, blocking=False):
    # The worker survives Hub restarts; the kernel releases this lock on a crash.
    import fcntl
    Path(directory).mkdir(mode=0o700, parents=True, exist_ok=True)
    with (Path(directory) / 'worker.lock').open('a') as stream:
        try:
            fcntl.flock(stream, fcntl.LOCK_EX | (0 if blocking else fcntl.LOCK_NB))
        except BlockingIOError:
            raise RuntimeError('Обновление панели уже выполняется.')
        try:
            yield
        finally:
            fcntl.flock(stream, fcntl.LOCK_UN)


def hub_update_validate(data):
    if not 50000 <= len(data) <= HUB_UPDATE_LIMIT:
        raise ValueError('Некорректный размер файла обновления панели.')
    source = data.decode('utf-8')
    if not all(marker in source for marker in ('class App:', 'class Handler(', 'def dashboard_html(', 'def main():')):
        raise ValueError('Источник вернул файл, не похожий на панель Hub.')
    if not all(marker in source for marker in ('class HubUpdateManager:', 'panel-update-worker', 'HUB_LOADED_REVISION')):
        raise ValueError('Сборка в источнике ещё не поддерживает проверяемое обновление из панели.')
    with warnings.catch_warnings():
        warnings.simplefilter('ignore', SyntaxWarning)
        compile(source, 'owrt-remote-hub.py', 'exec', dont_inherit=True)
    return data


def hub_update_older_version(candidate_version, installed_version):
    candidate = re.fullmatch(r'v([0-9]+)', candidate_version)
    installed = re.fullmatch(r'v([0-9]+)', installed_version)
    return bool(candidate and installed and int(candidate[1]) < int(installed[1]))


def hub_update_require_version(data, installed_version):
    version = hub_update_version(data)
    if hub_update_older_version(version, installed_version):
        raise ValueError('В источнике более старая версия ' + version + ', установлена '
                         + installed_version + '. Понижение версии через обновление панели запрещено.')


def hub_update_health(url, revision, attempts=30):
    for _ in range(attempts):
        try:
            with urllib.request.urlopen(url + '?panel-update=1', timeout=2) as response:
                data = json.loads(response.read(4096))
            if data.get('ok') and data.get('revision') == revision:
                return True
        except (OSError, ValueError):
            pass
        time.sleep(2)
    return False


def run_hub_update_worker(job_id, directory=None, target=None):
    directory = Path(directory or STATE_DIR / 'panel-update')
    target = Path(target or Path(__file__).resolve())
    with hub_update_lock(directory, blocking=True):
        job = hub_update_state(directory)
        if job.get('id') != job_id or job.get('status') != 'starting':
            raise RuntimeError('Задача обновления устарела или уже запущена.')
        changed = False
        maintenance_installed = False
        previous = None
        previous_mobile = None
        mobile_changed = False
        mobile_target = target.with_name('mobile_api.py')
        candidate = directory / 'candidate.py'
        def report(status, message):
            job.update(status=status, message=message, updated_at=time.time())
            hub_update_state(directory, job)
        try:
            time.sleep(2)  # Give the initiating HTTP request time to return its job id.
            data = hub_update_validate(candidate.read_bytes())
            if hashlib.sha256(data).hexdigest() != job.get('revision'):
                raise RuntimeError('Контрольная сумма обновления не совпала; файл не заменён.')
            previous = target.read_bytes()
            if hashlib.sha256(previous).hexdigest() != job.get('previous_revision'):
                raise RuntimeError('Файл Hub изменился после подтверждения; обнови страницу.')
            hub_update_require_version(data, hub_update_version(previous))
            mobile_data, _ = hub_mobile_api_payload(data)
            previous_mobile = mobile_target.read_bytes() if mobile_target.exists() else None
            hub_update_write(directory / 'previous.py', previous, 0o700)
            if previous_mobile is not None:
                hub_update_write(directory / 'previous-mobile-api.py', previous_mobile, 0o600)
                (directory / 'previous-mobile-api.absent').unlink(missing_ok=True)
            else:
                hub_update_write(directory / 'previous-mobile-api.absent', b'', 0o600)
                (directory / 'previous-mobile-api.py').unlink(missing_ok=True)
            report('installing', 'Устанавливается обслуживание журналов; проверяется очистка и таймер…')
            hub_install_log_maintenance(directory, job_id, source=data)
            maintenance_installed = True
            report('installing', 'Устанавливается новая сборка панели…')
            hub_update_write(mobile_target, mobile_data, 0o644)
            mobile_changed = True
            hub_update_write(target, data, 0o755)
            changed = True
            report('restarting', 'Панель перезапускается; ожидается проверка новой сборки…')
            subprocess.run(['systemctl', 'restart', 'owrt-remote'], check=True, capture_output=True, timeout=35)
            if not hub_update_health(job['health_url'], job['revision']):
                raise RuntimeError('Новая сборка не прошла проверку работоспособности.')
            report('succeeded', 'Панель обновлена. Обслуживание журналов и таймер проверены. Страница будет перезагружена.')
            try:
                hub_prune_log_maintenance_backups(directory, job_id)
            except OSError as cleanup_error:
                print('Не удалось убрать старую резервную копию обслуживания журналов: ' + str(cleanup_error), file=sys.stderr)
            return 0
        except Exception as exc:
            reason = str(exc)[:500]
            if maintenance_installed:
                try:
                    hub_rollback_log_maintenance(directory, job_id)
                except Exception as rollback_exc:
                    reason += ' Ошибка отката настроек журналов: ' + str(rollback_exc)[:300]
            if (changed or mobile_changed) and previous is not None:
                try:
                    report('rollback', 'Ошибка обновления; восстанавливается предыдущая сборка…')
                except OSError:
                    pass  # A full state disk must not prevent recovery of the Hub file.
                try:
                    hub_update_write(target, previous, 0o755)
                    if mobile_changed:
                        if previous_mobile is None:
                            mobile_target.unlink(missing_ok=True)
                        else:
                            hub_update_write(mobile_target, previous_mobile, 0o644)
                    subprocess.run(['systemctl', 'restart', 'owrt-remote'], check=True, capture_output=True, timeout=35)
                    restored = hub_update_health(job['health_url'], job['previous_revision'], attempts=15)
                    reason += ' Предыдущий файл восстановлен.' + ('' if restored else ' Работоспособность сервиса не подтверждена; проверь журнал owrt-remote на VPS.')
                except Exception as rollback_exc:
                    reason += ' Не удалось завершить откат: ' + str(rollback_exc)[:300]
            report('failed', 'Обновление не выполнено: ' + reason)
            return 1
        finally:
            candidate.unlink(missing_ok=True)


class HubUpdateManager:
    check_interval = 300

    def __init__(self, target=None, directory=None, source=None):
        self.target = Path(target or Path(__file__).resolve())
        self.directory = Path(directory or STATE_DIR / 'panel-update')
        self.source = (source or RAW_REPO_BASE).rstrip('/')
        self.csrf = secrets.token_urlsafe(32)
        self.lock = threading.Lock()
        self.checked_at = 0
        self.checking = False
        self.error = ''
        self.source_incompatible = ''
        self.candidate = None
        self.remote_revision = ''
        self.remote_version = ''
        self.health_url = 'http://127.0.0.1:8088/health'
        self.log_maintenance_status = ''
        self.log_maintenance_error = ''

    def resume_log_maintenance(self):
        """Bridge the first update, whose still-running worker is from old Hub.

        That worker waits for the new Hub's revision health. Hold only that
        health confirmation until installation finishes; heartbeat stays live.
        New workers install the component beforehand and already have a receipt.
        """
        if self.log_maintenance_status:
            return
        job = hub_update_state(self.directory)
        if (job.get('status') not in {'restarting', 'succeeded'} or job.get('revision') != HUB_LOADED_REVISION
                or time.time() - job.get('started_at', 0) > 420):
            return
        receipt = hub_log_maintenance_receipt(self.directory, job.get('id'))
        if receipt.get('status') == 'ready' and receipt.get('sha256') == HUB_LOG_MAINTENANCE_SHA256:
            return
        self.log_maintenance_status = 'installing'
        def install():
            try:
                # Hub has only CAP_NET_BIND_SERVICE. Provision via PID 1, like
                # the regular updater, so nginx tests/rotation have root caps.
                hub_run_log_maintenance_unit(self.directory, job['id'], self.target)
                self.log_maintenance_status = 'ready'
                try:
                    hub_prune_log_maintenance_backups(self.directory, job['id'])
                except OSError as cleanup_error:
                    print('Не удалось убрать старую резервную копию обслуживания журналов: ' + str(cleanup_error), file=sys.stderr)
            except Exception as exc:
                self.log_maintenance_error = str(exc)[:2000]
                self.log_maintenance_status = 'failed'
                print('Ошибка установки обслуживания журналов при обновлении: ' + str(exc), file=sys.stderr)
        try:
            threading.Thread(target=install, name='owrt-log-maintenance-bootstrap', daemon=True).start()
        except Exception as exc:
            self.log_maintenance_error = str(exc)[:2000]
            self.log_maintenance_status = 'failed'

    def check(self, force=False):
        with self.lock:
            job = hub_update_state(self.directory)
            if self.checking or job.get('status') in HUB_UPDATE_ACTIVE:
                return
            if self.checked_at and time.monotonic() - self.checked_at < (15 if force else self.check_interval):
                return
            self.checking = True
        try:
            threading.Thread(target=self._check, name='owrt-panel-update-check', daemon=True).start()
        except Exception:
            with self.lock:
                self.checking = False
            raise

    def fetch_candidate(self):
        if urllib.parse.urlsplit(self.source).scheme != 'https':
            raise ValueError('Источник обновления должен использовать HTTPS.')
        request = urllib.request.Request(self.source + '/vps/owrt-remote-hub.py', headers={
            'User-Agent': 'OpenWrt-Remote-Hub-Updater', 'Cache-Control': 'no-cache'})
        with urllib.request.urlopen(request, timeout=15) as response:
            if urllib.parse.urlsplit(response.geturl()).scheme != 'https':
                raise ValueError('Источник обновления должен использовать HTTPS.')
            return response.read(HUB_UPDATE_LIMIT + 1)

    def _check(self):
        data, error, incompatibility = None, '', ''
        try:
            data = self.fetch_candidate()
            hub_update_validate(data)
            hub_log_maintenance_payload(data)
            data = hub_preserve_mobile_api(data)
        except HubUpdateSourceUnsupported as exc:
            incompatibility = str(exc)
        except Exception as exc:
            error = 'Не удалось проверить обновление: ' + str(exc)[:300]
        with self.lock:
            self.checked_at = time.monotonic()
            self.error = error
            self.source_incompatible = incompatibility
            self.candidate = data if not error and not incompatibility else None
            self.remote_revision = hashlib.sha256(data).hexdigest() if not error else ''
            self.remote_version = hub_update_version(data) if not error else ''
            self.checking = False

    def snapshot(self):
        with self.lock:
            job = hub_update_state(self.directory)
            if job.get('revision') == HUB_LOADED_REVISION:
                if self.log_maintenance_status == 'installing':
                    job = {**job, 'status': 'installing', 'message': 'Настраивается обслуживание журналов; ожидается проверка очистки и таймера…'}
                elif self.log_maintenance_status == 'failed':
                    job = {**job, 'status': 'failed', 'message': 'Обслуживание журналов не установлено: ' + self.log_maintenance_error}
            if job.get('status') in HUB_UPDATE_ACTIVE and time.time() - job.get('started_at', 0) > 420:
                job.update(status='failed', message='Процесс обновления прерван. Итог не подтверждён; проверь сервис owrt-remote на VPS.')
                hub_update_state(self.directory, job)
            revision = HUB_LOADED_REVISION
            source_older = hub_update_older_version(self.remote_version, HUB_LOADED_VERSION)
            return {'checking': self.checking, 'error': self.error, 'source': self.source,
                    'current_revision': revision, 'current_version': HUB_LOADED_VERSION,
                    'remote_revision': self.remote_revision, 'source_older': source_older,
                    'source_incompatible': bool(self.source_incompatible), 'notice': self.source_incompatible,
                    'remote_version': self.remote_version, 'checked': bool(self.checked_at),
                    'available': bool(self.remote_revision and self.remote_revision != revision
                                      and not source_older and not self.source_incompatible),
                    'job': job, 'csrf': self.csrf}

    def start(self, revision):
        with self.lock:
            with hub_update_lock(self.directory):
                job = hub_update_state(self.directory)
                if job.get('status') in HUB_UPDATE_ACTIVE:
                    raise RuntimeError('Обновление панели уже выполняется.')
                if self.log_maintenance_status == 'installing':
                    raise RuntimeError('Ещё устанавливается обслуживание журналов.')
                if self.source_incompatible:
                    raise ValueError(self.source_incompatible)
                if not revision or revision != self.remote_revision or not self.candidate or self.error or self.checking:
                    raise ValueError('Результат проверки устарел. Проверь обновление ещё раз.')
                if revision == HUB_LOADED_REVISION:
                    raise ValueError('Эта сборка панели уже установлена.')
                hub_update_validate(self.candidate)
                hub_update_require_version(self.candidate, HUB_LOADED_VERSION)
                hub_mobile_api_payload(self.candidate)
                if shutil.disk_usage(self.target.parent).free < HUB_UPDATE_LIMIT * 3:
                    raise RuntimeError('Недостаточно свободного места для обновления и резервной копии.')
                if shutil.disk_usage(self.directory).free < HUB_UPDATE_LIMIT * 3:
                    raise RuntimeError('Недостаточно свободного места для резервной копии панели.')
                job = {'id': secrets.token_hex(16), 'status': 'starting', 'started_at': time.time(),
                       'message': 'Запускается обновление панели…', 'revision': revision,
                       'version': self.remote_version, 'previous_revision': HUB_LOADED_REVISION,
                       'health_url': self.health_url}
                hub_update_write(self.directory / 'candidate.py', self.candidate)
                hub_update_state(self.directory, job)
                try:
                    subprocess.run(['systemd-run', '--unit=owrt-remote-panel-update-' + job['id'], '--collect',
                                    '--property=RuntimeMaxSec=360', '--setenv=OWRT_REMOTE_STATE_DIR=' + str(STATE_DIR),
                                    sys.executable, str(self.target), 'panel-update-worker', '--job-id', job['id']],
                                   check=True, capture_output=True, timeout=15)
                except Exception as exc:
                    job.update(status='failed', message='Не удалось запустить обновление через systemd: ' + str(exc)[:300])
                    hub_update_state(self.directory, job)
                    (self.directory / 'candidate.py').unlink(missing_ok=True)
                    raise RuntimeError(job['message'])
        return job


class RouterAvailabilityHistory:
    """Minute observations shared by all viewers; gaps are never backfilled."""
    interval = 60
    window = 24 * 3600

    def __init__(self):
        self.lock = threading.RLock()
        self.last_bucket = None
        self.pruned_hour = None
        self.cache = OrderedDict()

    def record(self, conn, routers, at=None):
        at = now_ts() if at is None else int(at)
        bucket = at // self.interval * self.interval
        with self.lock:
            if bucket == self.last_bucket:
                return
            # Replace an incomplete minute after a Hub restart, rather than
            # counting two observations or retaining routers removed that minute.
            conn.execute('delete from router_availability where bucket=?', (bucket,))
            conn.executemany('insert into router_availability values (?, ?, ?, ?)', [
                (bucket, str(router['id']), at, int(bool(router.get('online'))))
                for router in routers
            ])
            hour = at // 3600
            if hour != self.pruned_hour:
                conn.execute('delete from router_availability where bucket<? or bucket>?',
                             (bucket - self.window - 3600, bucket))
            # Commit before publishing the cache generation or successful tick.
            conn.commit()
            self.pruned_hour = hour
            self.last_bucket = bucket
            self.cache.clear()

    def snapshot(self, conn, routers, at=None):
        at = now_ts() if at is None else int(at)
        ids = tuple(sorted(str(router['id']) for router in routers))
        key = (at // self.interval, ids)
        with self.lock:
            points = self.cache.get(key)
            if points is None:
                merged = {}
                # Stay below SQLite's variable limit on older distributions.
                for offset in range(0, len(ids), 400):
                    chunk = ids[offset:offset + 400]
                    query = '''select bucket, max(observed_at) as at,
                                      sum(online) as online, count(*) as total
                               from router_availability
                               where bucket>=? and bucket<=? and router_id in (%s)
                               group by bucket''' % ','.join('?' for _ in chunk)
                    for row in conn.execute(query, (at - self.window - self.interval, at, *chunk)):
                        point = merged.setdefault(row['bucket'], [0, 0, 0])
                        point[0] = max(point[0], row['at'])
                        point[1] += row['online']
                        point[2] += row['total']
                points = [merged[bucket] for bucket in sorted(merged)]
                self.cache[key] = points
                while len(self.cache) > 16:
                    self.cache.popitem(last=False)
            else:
                self.cache.move_to_end(key)
        return {'from': at - self.window, 'to': at, 'interval': self.interval,
                'gap_after': 90, 'points': points}


class App:
    def __init__(self, db_path, session, agent, public_url):
        self.db_path = Path(db_path)
        self.session_token = session
        self.agent_token = agent
        self.public_url = public_url.rstrip("/")
        self.router_state_lock = threading.Lock()
        self.xray_control_csrf = secrets.token_urlsafe(32)
        self.router_state_snapshot = {}
        self.router_monitor_stop = threading.Event()
        self.router_monitor_thread = None
        self.router_availability = RouterAvailabilityHistory()
        self.vps_resources = VpsResourceMonitor()
        self.router_updates = RouterUpdateManager(self)
        self.hub_update = HubUpdateManager()

    @contextmanager
    def conn(self):
        with connect(self.db_path) as conn:
            init_db(conn)
            yield conn

    def snapshot_router_states(self):
        with self.conn() as conn:
            routers = [row_to_router(row) for row in list_router_rows(conn)]
            self.router_availability.record(conn, routers)
        return {
            str(router.get("id") or ""): {
                "online": bool(router.get("online")),
                "router": router,
            }
            for router in routers
            if str(router.get("id") or "").strip()
        }

    def prime_router_state_snapshot(self):
        snapshot = self.snapshot_router_states()
        with self.router_state_lock:
            self.router_state_snapshot = snapshot

    def check_router_state_changes(self):
        current = self.snapshot_router_states()
        with self.router_state_lock:
            previous = dict(self.router_state_snapshot)
            self.router_state_snapshot = current
        for router_id, old in previous.items():
            new = current.get(router_id)
            if not new:
                continue
            if bool(old.get("online")) and not bool(new.get("online")):
                notify_router_offline(new.get("router") or {})

    def router_state_monitor_loop(self):
        interval = max(3, int(os.environ.get("OWRT_REMOTE_ROUTER_NOTIFY_POLL", "5")))
        try:
            self.prime_router_state_snapshot()
        except Exception as exc:
            print(f"WARNING: router state monitor initialization error: {exc}", file=sys.stderr)
        while not self.router_monitor_stop.wait(interval):
            try:
                self.check_router_state_changes()
            except Exception as exc:
                print(f"WARNING: router state monitor error: {exc}", file=sys.stderr)
            expire_ssh_http_sessions()

    def start_router_state_monitor(self):
        if self.router_monitor_thread and self.router_monitor_thread.is_alive():
            return
        self.router_monitor_stop.clear()
        self.router_monitor_thread = threading.Thread(target=self.router_state_monitor_loop, daemon=True)
        self.router_monitor_thread.start()

    def stop_router_state_monitor(self):
        self.router_monitor_stop.set()
        thread = self.router_monitor_thread
        if thread and thread.ident is not None and thread is not threading.current_thread():
            thread.join(timeout=10)


class Handler(BaseHTTPRequestHandler):
    server_version = "owrt-remote-hub/1.0"
    protocol_version = "HTTP/1.1"

    @property
    def app(self):
        return self.server.app

    def log_message(self, fmt, *args):
        # Only suppress ordinary successful access records. Application errors,
        # audit events and 4xx/5xx responses must still reach stderr/journald.
        path = urllib.parse.urlsplit(str(getattr(self, "path", "") or "")).path
        status = 0
        if fmt == '"%s" %s %s' and len(args) == 3:
            try:
                status = int(str(args[1]))
            except (TypeError, ValueError):
                status = 0
        quiet = (
            path == "/api/notifications/wait"
            or path in ("/api/heartbeat",)
            or re.fullmatch(r"/api/ssh-session/[^/]+/read", path or "")
        )
        debug = os.environ.get("OWRT_REMOTE_HTTP_DEBUG", "").lower() in ("1", "true", "yes")
        if quiet and 200 <= status < 400 and not debug:
            return
        sys.stderr.write("%s - - [%s] %s\n" % (self.address_string(), self.log_date_time_string(), fmt % args))

    def parsed(self):
        return urllib.parse.urlsplit(self.path)

    def query(self):
        return urllib.parse.parse_qs(self.parsed().query)

    def maybe_proxy_luci_absolute(self, path):
        if not any(path == root or path.startswith(root + "/") for root in LUCI_ABSOLUTE_ROOTS):
            return False
        router_id = ""
        ref_path = urllib.parse.urlsplit(self.headers.get("Referer", "")).path
        parts = ref_path.split("/", 3)
        if len(parts) >= 3 and parts[1] == "access" and parts[2]:
            router_id = parts[2]
        if not router_id:
            router_id = urllib.parse.unquote(parse_cookies(self.headers.get("Cookie", "")).get(ROUTER_COOKIE, ""))
        if router_id:
            self.proxy_access(f"/access/{router_id}{path}")
            return True
        return False

    def client_ip(self):
        forwarded = self.headers.get("X-Forwarded-For", "")
        if forwarded:
            return forwarded.split(",", 1)[0].strip()
        try:
            return self.client_address[0]
        except Exception:
            return ""

    def maybe_serve_ios_install(self, path):
        if path in {"/ios-install", "/ios-install/"}:
            self.send_bytes(200, ios_install_html(self.query().get('next', ['/'])[0]).encode('utf-8'), 'text/html; charset=utf-8')
            return True
        if not ios_hub_document_path(path):
            return False
        if not re.search(r'iPad|iPhone|iPod', self.headers.get('User-Agent', ''), re.I):
            return False
        # This cookie is only a display hint. Authentication is still checked
        # independently; the early head gate verifies the actual window mode.
        if parse_cookies(self.headers.get('Cookie', '')).get(IOS_APP_HINT_COOKIE) == 'standalone':
            return False
        self.send_bytes(200, ios_install_html(self.path).encode('utf-8'), 'text/html; charset=utf-8')
        return True

    def current_session_token(self):
        return parse_cookies(self.headers.get("Cookie", "")).get(SESSION_COOKIE, "")

    def current_hub_session(self, touch=True):
        return verify_hub_session(
            self.current_session_token(),
            touch=touch,
            ip=self.client_ip() if touch else "",
            user_agent=self.headers.get("User-Agent", "") if touch else "",
        )

    def legacy_admin_ok(self):
        return secrets.compare_digest(self.current_session_token(), self.app.session_token)

    def admin_ok(self):
        return bool(self.current_hub_session()) or self.legacy_admin_ok()

    def current_account_profile(self, touch=True):
        auth = normalize_auth_state(load_auth())
        if self.legacy_admin_ok():
            return account_profile(auth, auth.get("username", "admin"))
        session = self.current_hub_session(touch=touch)
        if not session:
            return None
        return account_profile(auth, session.get("username", ""))

    def owner_ok(self):
        profile = self.current_account_profile(touch=False)
        return bool(profile and profile.get("is_owner"))

    def can_add_router(self):
        profile = self.current_account_profile(touch=False)
        return bool(profile and account_can_add_router(profile))

    def require_owner(self, json_mode=False):
        if self.owner_ok():
            return True
        if not self.admin_ok():
            if json_mode:
                self.send_json(401, {"ok": False, "error": "not authorized"})
            else:
                self.send_bytes(401, login_html().encode("utf-8"), "text/html; charset=utf-8")
            return False
        if json_mode:
            self.send_json(403, {"ok": False, "error": "Недостаточно прав"})
        else:
            self.send_text(403, "Недостаточно прав")
        return False

    def require_add_router(self, json_mode=False):
        if self.can_add_router():
            return True
        if not self.admin_ok():
            if json_mode:
                self.send_json(401, {"ok": False, "error": "not authorized"})
            else:
                self.send_bytes(401, login_html().encode("utf-8"), "text/html; charset=utf-8")
            return False
        if json_mode:
            self.send_json(403, {"ok": False, "error": "Недостаточно прав для добавления роутера"})
        else:
            self.send_text(403, "Недостаточно прав для добавления роутера")
        return False

    def router_access_allowed(self, router_id, flag):
        profile = self.current_account_profile()
        return bool(profile and account_has_router_flag(profile, router_id, flag))

    def require_router_access(self, router_id, flag, json_mode=False):
        if self.router_access_allowed(router_id, flag):
            return True
        if not self.admin_ok():
            if json_mode:
                self.send_json(401, {"ok": False, "error": "not authorized"})
            else:
                self.send_bytes(401, login_html().encode("utf-8"), "text/html; charset=utf-8")
            return False
        if json_mode:
            self.send_json(403, {"ok": False, "error": "Недостаточно прав для этого роутера"})
        else:
            self.send_text(403, "Недостаточно прав для этого роутера")
        return False

    def current_or_owner_session_scope(self):
        profile = self.current_account_profile(touch=False)
        if not profile or profile.get("is_owner"):
            return ""
        return str(profile.get("username") or "")

    def router_order_scope(self, profile):
        return 'owner' if profile.get('is_owner') else 'user:' + str(profile.get('username') or '')

    def router_display_order(self, conn, profile, routers):
        saved = conn.execute('select ids_json from router_display_order where account=?',
                             (self.router_order_scope(profile),)).fetchone()
        allowed = {router['id'] for router in routers}
        return [key for key in json.loads(saved['ids_json']) if key in allowed] if saved else []

    def move_router_card(self):
        profile = self.current_account_profile(touch=False)
        if not profile:
            self.send_json(401, {'ok': False, 'error': 'Нужен вход в Hub'})
            return
        # A browser cannot send this header cross-origin without a CORS preflight.
        origin = self.headers.get('Origin')
        if (self.headers.get('X-Router-Order') != '1'
                or self.headers.get('Content-Type', '').split(';')[0].strip() != 'application/json'
                or (origin and origin != self.request_origin())):
            self.send_json(403, {'ok': False, 'error': 'Request origin is not allowed'})
            return
        try:
            payload = self.read_payload()
            key, target, placement = payload.get('id'), payload.get('target'), payload.get('placement')
            if not isinstance(key, str) or not isinstance(target, str) or key == target or placement not in ('before', 'after'):
                raise ValueError('Неверное перемещение карточки')
            with self.app.conn() as conn:
                # Serialize read-modify-write so moves in other tabs cannot erase each other.
                conn.execute('begin immediate')
                routers = self.visible_routers(conn, profile)
                allowed = {router['id'] for router in routers}
                if key not in allowed or target not in allowed:
                    self.send_json(404, {'ok': False, 'error': 'Роутер недоступен'})
                    return
                saved = self.router_display_order(conn, profile, routers)
                base = payload.get('base_order', [])
                if not isinstance(base, list) or len(base) > 10000 or any(not isinstance(item, str) for item in base):
                    raise ValueError('Неверный порядок карточек')
                ids = list(dict.fromkeys(saved + [item for item in base if item in allowed]
                           + [r['id'] for r in sorted(routers, key=lambda r: (r.get('name') or r['id']).casefold())]))
                ids.remove(key)
                ids.insert(ids.index(target) + (placement == 'after'), key)
                conn.execute('insert into router_display_order(account, ids_json) values(?, ?) '
                             'on conflict(account) do update set ids_json=excluded.ids_json',
                             (self.router_order_scope(profile), json.dumps(ids)))
            self.send_json(200, {'ok': True, 'router_order': ids})
        except (ValueError, TypeError, json.JSONDecodeError) as error:
            self.send_json(400, {'ok': False, 'error': str(error)})

    def visible_routers(self, conn, account=None):
        profile = account or self.current_account_profile()
        routers = [row_to_router(r) for r in list_router_rows(conn)]
        if profile and not profile.get("is_owner"):
            allowed = set(profile.get("router_ids") or [])
            routers = [router for router in routers if str(router.get("id") or "") in allowed]
        positions = {key: index for index, key in enumerate(self.router_display_order(conn, profile, routers))}
        return [dict(router_with_access(router, profile), display_order=positions.get(router['id'])) for router in routers]

    def ssh_token_ok(self, router_id):
        token = self.query().get("t", [""])[0]
        if not token:
            return False
        return secrets.compare_digest(token, ssh_ws_token(self.app.session_token, router_id))

    def agent_ok(self):
        auth = self.headers.get("Authorization", "")
        if auth.startswith("Bearer "):
            return secrets.compare_digest(auth[7:].strip(), self.app.agent_token)
        return False

    def send_bytes(self, status, body, content_type="text/plain; charset=utf-8", extra_headers=None):
        body = inject_hub_appearance(getattr(self, "path", ""), body, content_type)
        self.close_connection = True
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Connection", "close")
        if extra_headers:
            for key, value in extra_headers:
                if key.lower() in {"connection", "content-length", "content-type", "cache-control"}:
                    continue
                self.send_header(key, value)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            try:
                self.wfile.write(body)
                self.wfile.flush()
            except (BrokenPipeError, ConnectionResetError, ssl.SSLError):
                pass

    def send_raw_bytes(self, status, body, content_type="application/octet-stream", extra_headers=None):
        self.close_connection = True
        reason = self.responses.get(status, ("OK",))[0]
        headers = [
            f"{self.protocol_version} {status} {reason}",
            f"Server: {self.version_string()}",
            f"Date: {self.date_time_string()}",
            f"Content-Type: {content_type}",
            "Cache-Control: no-store",
            "Connection: close",
            f"Content-Length: {len(body)}",
        ]
        if extra_headers:
            for key, value in extra_headers:
                low = key.lower()
                if low in {"connection", "content-length", "content-type", "cache-control"}:
                    continue
                safe_key = str(key).replace("\r", "").replace("\n", "")
                safe_value = str(value).replace("\r", "").replace("\n", "")
                headers.append(f"{safe_key}: {safe_value}")
        raw = ("\r\n".join(headers) + "\r\n\r\n").encode("iso-8859-1", "replace")
        if self.command != "HEAD":
            raw += body
        try:
            self.request.sendall(raw)
            self.log_request(status, len(body))
        except (BrokenPipeError, ConnectionResetError, ssl.SSLError):
            pass

    def send_text(self, status, text, content_type="text/plain; charset=utf-8"):
        self.send_bytes(status, text.encode("utf-8"), content_type)

    def send_local_asset(self, file_path, content_type):
        embedded = HUB_BRAND_ASSETS.get(Path(file_path).name)
        if embedded:
            self.send_bytes(200, base64.b64decode(embedded), content_type)
            return
        try:
            body = Path(file_path).read_bytes()
        except FileNotFoundError:
            self.send_text(404, "asset not found")
            return
        self.send_bytes(200, body, content_type)

    def send_json(self, status, payload, extra_headers=None):
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_bytes(status, body, "application/json; charset=utf-8", extra_headers=extra_headers)

    def require_admin(self):
        if self.admin_ok():
            return True
        self.send_bytes(401, login_html().encode("utf-8"), "text/html; charset=utf-8")
        return False

    def read_body(self):
        if self.headers.get("Transfer-Encoding", "").lower() == "chunked":
            chunks = []
            while True:
                raw_line = self.rfile.readline()
                if not raw_line:
                    raise ValueError("incomplete chunked request body")
                line = raw_line.strip()
                size = int(line.split(b";", 1)[0], 16)
                if size < 0:
                    raise ValueError("negative chunk size")
                if size == 0:
                    while True:
                        trailer = self.rfile.readline()
                        if not trailer:
                            raise ValueError("incomplete chunked request trailers")
                        if trailer == b"\r\n":
                            break
                    break
                chunk = self.rfile.read(size)
                if len(chunk) != size or self.rfile.read(2) != b"\r\n":
                    raise ValueError("incomplete chunked request data")
                chunks.append(chunk)
            return b"".join(chunks)
        length = int(self.headers.get("Content-Length", "0") or "0")
        if length < 0:
            raise ValueError("negative content length")
        body = self.rfile.read(length) if length else b""
        if len(body) != length:
            raise ValueError("incomplete request body")
        return body

    def read_payload(self, *, keep_blank_values=False):
        body = self.read_body()
        ctype = self.headers.get("Content-Type", "")
        if "application/json" in ctype:
            return json.loads(body.decode("utf-8") or "{}")
        if "multipart/form-data" in ctype.lower():
            message = BytesParser(policy=email_policy_default).parsebytes(
                b"Content-Type: " + ctype.encode("utf-8", errors="replace") + b"\r\nMIME-Version: 1.0\r\n\r\n" + body
            )
            payload = {"__files__": {}}
            if not message.is_multipart():
                return payload
            for part in message.iter_parts():
                if part.get_content_disposition() != "form-data":
                    continue
                name = str(part.get_param("name", header="content-disposition") or "").strip()
                if not name:
                    continue
                filename = part.get_filename()
                raw = part.get_payload(decode=True) or b""
                if filename is not None:
                    payload["__files__"].setdefault(name, []).append(
                        {
                            "filename": filename,
                            "content_type": part.get_content_type() or "",
                            "body": raw,
                        }
                    )
                    continue
                payload[name] = raw.decode(part.get_content_charset() or "utf-8", errors="replace")
            return payload
        parsed = urllib.parse.parse_qs(body.decode("utf-8"), keep_blank_values=keep_blank_values)
        return {k: v[-1] for k, v in parsed.items()}

    def session_cookie(self, token):
        secure = "; Secure" if self.request_scheme() == "https" else ""
        expires = formatdate(now_ts() + SESSION_TTL_SECONDS, usegmt=True)
        return f"{SESSION_COOKIE}={token}; HttpOnly; SameSite=Lax; Path=/; Max-Age={SESSION_TTL_SECONDS}; Expires={expires}{secure}"

    def clear_session_cookie(self):
        secure = "; Secure" if self.request_scheme() == "https" else ""
        return f"{SESSION_COOKIE}=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT{secure}"

    def request_scheme(self):
        forwarded = str(self.headers.get("X-Forwarded-Proto", "")).split(",", 1)[0].strip().lower()
        if forwarded in {"http", "https"}:
            return forwarded
        return "https" if isinstance(self.request, ssl.SSLSocket) else "http"

    def request_host(self):
        scheme = self.request_scheme()
        host = str(self.headers.get("X-Forwarded-Host") or self.headers.get("Host") or "").split(",", 1)[0].strip()
        forwarded_port = self.headers.get("X-Forwarded-Port", "")
        return append_forwarded_port(scheme, host, forwarded_port)

    def request_origin(self):
        return origin_from_parts(self.request_scheme(), self.request_host())

    def request_host_name(self):
        try:
            return urllib.parse.urlsplit(self.request_origin()).hostname or ""
        except Exception:
            return ""

    def webauthn_rp_id(self):
        return public_url_rp_id(self.app.public_url) or self.request_host_name()

    def webauthn_allowed_origins(self):
        values = []
        for item in (public_url_origin(self.app.public_url), self.request_origin()):
            if item and item not in values:
                values.append(item)
        return values

    def build_webauthn_server(self):
        if not passkey_supported():
            raise ValueError("На сервере не установлен модуль Passkey/WebAuthn")
        rp_id = self.webauthn_rp_id()
        origins = set(self.webauthn_allowed_origins())
        if not rp_id or not origins:
            raise ValueError("Не удалось определить origin/RP ID для Passkey")

        def verify_origin(origin):
            try:
                parts = urllib.parse.urlsplit(str(origin or ""))
                return origin_from_parts(parts.scheme, parts.netloc) in origins
            except Exception:
                return False

        return Fido2Server({"id": rp_id, "name": APP_NAME}, verify_origin=verify_origin)

    def require_current_password(self, payload, auth=None):
        auth = normalize_auth_state(auth or load_auth())
        current_password = str((payload or {}).get("current_password") or "")
        if not verify_login(auth.get("username", ""), current_password):
            raise ValueError("Текущий пароль неверный")
        return auth

    def verify_login_captcha(self, payload, auth=None):
        auth = normalize_auth_state(auth or load_auth())
        state = effective_captcha_state(auth)
        if state.get("effective_mode") in CAPTCHA_RECAPTCHA_MODES:
            token = (
                (payload or {}).get("g-recaptcha-response")
                or (payload or {}).get("recaptcha_token")
                or ""
            )
            return verify_recaptcha_token(
                state.get("secret_key", ""),
                token,
                remote_ip=self.client_ip(),
                expected_hostname=self.request_host_name(),
                expected_action=RECAPTCHA_V3_ACTION if state["effective_mode"] == CAPTCHA_MODE_RECAPTCHA_V3 else "",
                min_score=state["min_score"],
            )
        captcha_token = (payload or {}).get("captcha_token", "")
        captcha_answer = (payload or {}).get("captcha_answer", "")
        if verify_captcha(captcha_token, captcha_answer):
            return True, ""
        return False, "Неверная капча"

    def create_login_session(self, username="", auth_method="password"):
        session_username = str(username or current_username()).strip()
        token, session = make_hub_session(
            session_username,
            self.client_ip(),
            self.headers.get("User-Agent", ""),
            auth_method=auth_method,
        )
        add_notification(
            "login",
            "Вход в Hub",
            f"{session.get('client', 'устройство')} · {auth_method_label(auth_method)} · IP {session.get('ip', 'unknown')}",
            "warn",
            [session.get("user_agent", "")],
            {
                "session_id": session.get("id", ""),
                "username": session_username,
                "ip": session.get("ip", ""),
                "client": session.get("client", ""),
                "user_agent": session.get("user_agent", ""),
                "auth_method": auth_method,
            },
        )
        return token, session

    def send_login_json(self, username="", auth_method="password"):
        token, _ = self.create_login_session(username, auth_method)
        body = {
            "ok": True,
            "redirect": "/",
            "auth_method": auth_method,
            "username": username or current_username(),
        }
        self.send_bytes(
            200,
            json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
            "application/json; charset=utf-8",
            [("Set-Cookie", self.session_cookie(token))],
        )

    def social_callback_url(self, provider):
        provider = str(provider or "").strip().lower()
        base = public_url_origin(self.app.public_url) or self.request_origin()
        if not base:
            raise ValueError("Не удалось определить внешний URL Hub для OAuth callback")
        return f"{base}/oauth/{provider}/callback"

    def social_provider_config(self, provider, auth=None):
        provider = str(provider or "").strip().lower()
        if provider not in SOCIAL_PROVIDERS:
            raise ValueError("Неизвестный OAuth provider")
        auth = normalize_auth_state(auth or load_auth())
        return sanitize_social_provider_state(provider, auth.get("social", {}).get(provider))

    def social_flow_authorize_url(self, provider, state, redirect_uri, flow=None):
        provider = str(provider or "").strip().lower()
        cfg = self.social_provider_config(provider)
        if not social_provider_configured(provider, cfg):
            raise ValueError(social_provider_setup_message(provider))
        flow = dict(flow or {})
        if provider == "github":
            query = {
                "client_id": cfg["client_id"],
                "redirect_uri": redirect_uri,
                "scope": "read:user user:email",
                "state": state,
                "allow_signup": "false",
            }
        elif provider == "vk":
            code_verifier = str(flow.get("code_verifier") or "").strip()
            if not code_verifier:
                raise ValueError("VK ID flow не подготовлен")
            query = {
                "client_id": cfg["client_id"],
                "redirect_uri": redirect_uri,
                "response_type": "code",
                "scope": "email vkid.personal_info",
                "state": state,
                "code_challenge": make_pkce_challenge(code_verifier),
                "code_challenge_method": "S256",
            }
        else:
            raise ValueError("Неизвестный OAuth provider")
        return f"{SOCIAL_PROVIDERS[provider]['authorize_url']}?{urllib.parse.urlencode(query)}"

