        if path == "/login":
            if self.admin_ok():
                self.redirect("/", [("Set-Cookie", self.session_cookie(self.current_session_token()))])
                return
            self.send_bytes(200, login_html().encode("utf-8"), "text/html; charset=utf-8")
            return
        if path == "/api/session/status":
            if not self.admin_ok():
                self.send_json(401, {"ok": False, "authenticated": False})
                return
            self.send_json(200, {"ok": True, "authenticated": True},
                           [("Set-Cookie", self.session_cookie(self.current_session_token()))])
            return
